mapper.sql:
  ${params.sqlMap.default}
and  owi.is_deleted = FALSE
  AND owid.is_deleted = FALSE


      ${params.permissionSql}

  ORDER BY


          ${item.field} ${item.sort}


  owi.create_time DESC

where T.is_deleted = 'f' AND G.is_deleted = 'f' and h.is_deleted = 'f'
AND h.receive_time >= #{params.receiveDateList[0]} and (#{params.receiveDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > h.receive_time
AND t.to_warehouse_name = #{params.toWarehouseName}
